# Get current friends list (paginate)
all_friends = []
page_index = 0
while True:
    result = apis.venmo.search_friends(
        access_token=access_token,
        page_index=page_index,
        page_limit=20
    )
    if isinstance(result, list):
        all_friends.extend(result)
        if len(result) < 20:
            break
        page_index += 1
    else:
        print("Error or no more results:", result)
        break

print("Number of friends:", len(all_friends))
for f in all_friends:
    print(f)

